// Refinamento 02. Dados externos só são exibidos como atuais após resposta válida.
const baseApply=apply;
apply=function(){baseApply();const r=document.documentElement;r.style.setProperty('--glass',Math.min(60,Math.max(3,+prefs.glass||16))/100);r.style.setProperty('--blur',Math.min(48,Math.max(0,+prefs.blur||0))+'px');r.style.setProperty('--shine',Math.min(100,Math.max(0,+prefs.shine||0))/100);r.style.setProperty('--accent',/^#[0-9a-f]{6}$/i.test(prefs.accent)?prefs.accent:'#66d9ff');r.style.setProperty('--darkness',Math.min(85,Math.max(20,+prefs.darkness||52))/100);document.body.classList.toggle('text-large',prefs.font==='large');$('.landscape').style.backgroundImage=prefs.customWallpaper?'url('+JSON.stringify(prefs.customWallpaper)+')':'';};
let speedController=null;
const previousShow=show;
show=function(html){if(speedController){speedController.abort();speedController=null}const wasOpen=panel.open;const oldFocus=lastFocus;previousShow(html);if(wasOpen)lastFocus=oldFocus;};
panel.addEventListener('close',()=>{speedController?.abort();speedController=null});
function settingsMenu(){show('<p class="eyebrow">TUDO NO SEU LUGAR</p><h2>Configurações</h2><div class="panel-menu"><button id="menu-glass"><strong>Aparência e vidro</strong><small>Transparência, desfoque e cores</small></button><button id="menu-network"><strong>Rede e Wi-Fi</strong><small>Status e teste de velocidade</small></button><button id="menu-store"><strong>Play Store</strong><small>Loja de aplicativos</small></button><button id="menu-tv"><strong>Configurações da TV</strong><small>Imagem, som e sistema</small></button></div>');$('#menu-glass').onclick=appearance;$('#menu-network').onclick=networkPanel;$('#menu-store').onclick=storePanel;$('#menu-tv').onclick=()=>show('<p class="eyebrow">SISTEMA</p><h2>Configurações da TV</h2><p>No APK, este atalho abrirá as configurações do Android TV para imagem, som, Bluetooth e sistema.</p><p>A prévia no navegador não tem acesso às configurações da sua Konka.</p><button class="panel-button" id="back-settings">Voltar às configurações</button>');}
$('#system-settings').onclick=settingsMenu;
function storePanel(){show('<p class="eyebrow">SUA BIBLIOTECA PODE CRESCER</p><h2>Play Store</h2><p>Na TV, este botão abrirá a loja instalada. Aqui você pode consultar a loja oficial pelo navegador.</p><a class="panel-button external-link" href="https://play.google.com/store/apps?device=tv" target="_blank" rel="noopener noreferrer">Explorar Google Play ↗</a><p class="inline-note">A instalação e a compatibilidade com a Konka serão determinadas pela loja e pelo aparelho.</p>')}
$('#store').onclick=storePanel;
appearance=function(){const controls=[['glass','Intensidade do vidro',3,60,'%'],['blur','Desfoque do fundo',0,48,'px'],['shine','Reflexos e brilho',0,100,'%'],['darkness','Escurecer paisagem',20,85,'%']];show('<p class="eyebrow">VIDRO COM A SUA ASSINATURA</p><h2>Aparência e vidro</h2>'+controls.map(([id,label,min,max,unit])=>`<label class="option">${label}<span class="range-wrap"><input data-setting="${id}" type="range" min="${min}" max="${max}" value="${prefs[id]}" aria-label="${label}"><output id="out-${id}">${prefs[id]}${unit}</output></span></label>`).join('')+'<div class="option"><span>Cor de destaque</span><div class="accent-options">'+['#66d9ff','#b59aff','#f2bf84','#74e7b5','#ff8eaa'].map(c=>`<button class="accent-choice" data-accent="${c}" style="background:${c}" aria-label="Cor ${c}" aria-pressed="${prefs.accent===c}"></button>`).join('')+'</div></div>'+`<label class="option">Animações suaves<input id="motion-toggle" type="checkbox" ${prefs.motion?'checked':''}></label><label class="option">Tamanho do texto<select id="font-size"><option value="normal">Padrão</option><option value="large" ${prefs.font==='large'?'selected':''}>Ampliado</option></select></label><button id="change-scene" class="panel-button">Escolher paisagem</button><button id="reset-glass" class="text-button">Restaurar aparência</button>`);document.querySelectorAll('[data-setting]').forEach(el=>el.oninput=()=>{const id=el.dataset.setting;prefs[id]=+el.value;$('#out-'+id).textContent=el.value+(id==='blur'?'px':'%');apply()});document.querySelectorAll('[data-accent]').forEach(b=>b.onclick=()=>{prefs.accent=b.dataset.accent;apply();document.querySelectorAll('[data-accent]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});$('#motion-toggle').onchange=e=>{prefs.motion=e.target.checked;apply()};$('#font-size').onchange=e=>{prefs.font=e.target.value;apply()};$('#change-scene').onclick=scenes;$('#reset-glass').onclick=()=>{for(const key of ['glass','blur','shine','darkness','accent','motion','font'])prefs[key]=defaults[key];apply();appearance()}};
scenes=function(){show('<p class="eyebrow">UMA JANELA PARA FORA</p><h2>Seu ambiente</h2><p>Paisagens fotográficas ou uma imagem escolhida por você.</p><div class="scene-picker"><button class="scene-choice" data-scene="mountain">Montanhas</button><button class="scene-choice" data-scene="dusk">Lago alpino</button><button class="scene-choice" data-scene="forest">Floresta</button></div><label class="option">Usar minha imagem<input type="file" id="custom-wallpaper" accept="image/jpeg,image/png,image/webp"></label><p class="inline-note">Fotografias externas via Unsplash; não representam Contagem. Sua imagem é processada neste navegador.</p><button id="scene-glass" class="text-button">Ajustar vidro e contraste ↗</button>');document.querySelectorAll('.scene-choice').forEach(b=>{b.setAttribute('aria-pressed',String(prefs.scene===b.dataset.scene&&!prefs.customWallpaper));b.onclick=()=>{prefs.scene=b.dataset.scene;prefs.customWallpaper='';apply();scenes()}});$('#scene-glass').onclick=appearance;$('#custom-wallpaper').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){notify('Escolha uma imagem JPEG, PNG ou WebP.');return}try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const scale=Math.min(1,1920/bitmap.width);canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();prefs.customWallpaper=canvas.toDataURL('image/jpeg',.8);apply();notify('Sua paisagem está pronta.')}catch{notify('Não foi possível abrir esta imagem.')}}};
$('#wallpaper').onclick=scenes;$('#settings').onclick=settingsMenu;
function syncNetwork(){const online=navigator.onLine;$('#network-label').textContent=online?'Rede disponível':'Sem rede';$('.network-dot').classList.toggle('offline',!online);$('#network-pill').setAttribute('aria-label',online?'Rede disponível: ver status e velocidade':'Sem rede: ver detalhes');if($('#net-availability'))$('#net-availability').textContent=online?'Rede disponível':'Sem rede'}
addEventListener('online',syncNetwork);addEventListener('offline',syncNetwork);syncNetwork();
function networkPanel(){show('<p class="eyebrow">CONEXÃO EM FOCO</p><h2>Rede e Wi-Fi</h2><p class="inline-note">Status do aparelho que abriu esta prévia. O navegador não informa o nome da rede Wi-Fi nem controla as redes da TV.</p><div class="speed-box"><div class="speed-top"><strong id="net-availability"></strong><span>Mb/s</span></div><div class="speed-numbers"><div class="download"><small>↓ Download</small><strong id="down-value">—</strong></div><div class="upload"><small>↑ Upload</small><strong id="up-value">—</strong></div></div><svg class="speed-chart" viewBox="0 0 440 110" role="img" aria-label="Gráfico das amostras de download em azul e upload em lilás"><path class="grid" d="M10 15H430M10 55H430M10 95H430"/><polyline id="down-line" class="down-line"/><polyline id="up-line" class="up-line"/><text id="chart-message" x="220" y="55" text-anchor="middle">Inicie o teste para medir</text></svg><p id="speed-status" class="speed-status" aria-live="polite">Sem medição. Nenhum valor foi simulado.</p></div><button id="speed-start" class="panel-button">Medir velocidade</button><p class="inline-note">Estimativa de transferência HTTP até a Cloudflare. Usa cerca de 8 MB por teste; não mede o tráfego contínuo da TV. Pode variar com latência, cache e limites do navegador.</p><button id="wifi-settings" class="text-button">Configurar Wi-Fi na TV ↗</button>');syncNetwork();renderSignalDetail();restorePanelSpeed();$('#speed-start').onclick=runSpeedTest;$('#wifi-settings').onclick=()=>{show('<p class="eyebrow">REDE DA KONKA</p><h2>Configurar Wi-Fi</h2><p>Na TV: Configurações → Rede e Internet → Wi-Fi.</p><p>O APK terá um atalho para abrir esse painel do Android TV. Esta prévia web não altera a conexão.</p><button class="panel-button" id="return-net">Voltar ao painel de rede</button>');$('#return-net').onclick=networkPanel}}
$('#network').onclick=networkPanel;$('#network-pill').onclick=networkPanel;
function speedPoints(values,max){return values.map((v,i)=>`${10+i*210},${95-(v/max)*75}`).join(' ')}
async function runSpeedTest(){if(!navigator.onLine){notify('Conecte o aparelho à rede para medir.');return}const controller=new AbortController();speedController=controller;const down=[],up=[];$('#speed-start').disabled=true;$('#speed-start').textContent='Medindo…';$('#chart-message').textContent='';$('#down-line').setAttribute('points','');$('#up-line').setAttribute('points','');$('#down-value').textContent='—';$('#up-value').textContent='—';const timeout=setTimeout(()=>controller.abort(),45000);try{for(let i=0;i<3;i++){if(!$('#speed-status')||controller.signal.aborted)throw new Error('cancelled');$('#speed-status').textContent=`Download · amostra ${i+1} de 3`;let start=performance.now();const response=await fetch(`https://speed.cloudflare.com/__down?bytes=2097152&nonce=${Date.now()}-${i}`,{cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error('download');const buffer=await response.arrayBuffer();if(buffer.byteLength!==2097152)throw new Error('invalid-size');down.push(buffer.byteLength*8/(performance.now()-start)/1000);$('#down-value').textContent=(down.reduce((a,b)=>a+b,0)/down.length).toFixed(1);$('#speed-status').textContent=`Upload · amostra ${i+1} de 3`;const payload=new Uint8Array(524288);start=performance.now();const result=await fetch('https://speed.cloudflare.com/__up',{method:'POST',body:payload,signal:controller.signal});if(!result.ok)throw new Error('upload');await result.text();up.push(payload.byteLength*8/(performance.now()-start)/1000);$('#up-value').textContent=(up.reduce((a,b)=>a+b,0)/up.length).toFixed(1);const max=Math.max(1,...down,...up);$('#down-line').setAttribute('points',speedPoints(down,max));$('#up-line').setAttribute('points',speedPoints(up,max));updateHomeSpeed(down,up,i===2)}$('#speed-status').textContent='Concluído agora · média de 3 amostras em cada direção.';}catch(e){markHomeSpeedInterrupted();if($('#speed-status'))$('#speed-status').textContent=controller.signal.aborted?'Teste interrompido ou tempo limite atingido.':'Não foi possível concluir. O serviço pode estar indisponível ou bloqueado pelo navegador.';}finally{clearTimeout(timeout);if(speedController===controller){speedController=null;if($('#speed-start')){$('#speed-start').disabled=false;$('#speed-start').textContent='Medir novamente'}}}}
let weather=null,weatherError=false;
function weatherDescription(code){if(code===0)return'Céu limpo';if(code<=2)return'Parcialmente nublado';if(code===3)return'Nublado';if(code<=48)return'Névoa';if(code<=67)return'Chuva';if(code<=77)return'Neve';if(code<=82)return'Pancadas de chuva';if(code<=86)return'Neve';return'Trovoadas'}
function displayWeather(){if(!weather)return;$('#weather-temp').textContent=Math.round(weather.current.temperature_2m)+'°';$('#weather-condition').textContent=(weatherError?'Dados salvos · ':'')+weatherDescription(weather.current.weather_code)}
async function loadWeather(force=false){try{if(!force){const cached=JSON.parse(localStorage.getItem('konka-weather')||'null');if(cached?.current&&cached?.daily&&Number.isFinite(cached.current.temperature_2m)){weather=cached;displayWeather();if(Date.now()-cached.savedAt<1200000)return}}const response=await fetch('https://api.open-meteo.com/v1/forecast?latitude=-19.93&longitude=-44.05&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=America%2FSao_Paulo&forecast_days=3',{signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error('weather');const data=await response.json();if(!Number.isFinite(data.current?.temperature_2m)||!Array.isArray(data.daily?.time))throw new Error('invalid-weather');weather={...data,savedAt:Date.now()};weatherError=false;try{localStorage.setItem('konka-weather',JSON.stringify(weather))}catch{}displayWeather()}catch{weatherError=true;if(weather)displayWeather();else $('#weather-condition').textContent='Clima indisponível'}}
function weatherPanel(){const w=weather;show('<p class="eyebrow">CONTAGEM · MINAS GERAIS</p><h2>Clima da sua região</h2>'+(w?`<div class="weather-main">${Math.round(w.current.temperature_2m)}°</div><p>${weatherDescription(w.current.weather_code)} · Sensação ${Math.round(w.current.apparent_temperature)}°<br>Umidade ${w.current.relative_humidity_2m}% · Vento ${w.current.wind_speed_10m} km/h</p>`+w.daily.time.map((day,i)=>`<div class="forecast-row"><span>${i===0?'Hoje':new Intl.DateTimeFormat('pt-BR',{weekday:'short',timeZone:'America/Sao_Paulo'}).format(new Date(day+'T12:00:00-03:00'))}</span><span>${weatherDescription(w.daily.weather_code[i])}</span><strong>${Math.round(w.daily.temperature_2m_min[i])}° / ${Math.round(w.daily.temperature_2m_max[i])}°</strong></div>`).join('')+`<p class="inline-note">${weatherError?'Dados salvos. Última consulta falhou. ':''}Modelo meteorológico · referência ${w.current.time.replace('T',' ')} (horário de Brasília). Coordenadas aproximadas da cidade.</p>`:'<p>O clima ainda não está disponível. Conecte-se à internet e tente atualizar.</p>')+'<button class="panel-button" id="weather-refresh">Atualizar clima</button><a class="weather-credit" href="https://open-meteo.com/" target="_blank" rel="noopener">Dados: Open-Meteo · CC BY 4.0 ↗</a>');$('#weather-refresh').onclick=async()=>{$('#weather-refresh').disabled=true;await loadWeather(true);if($('#weather-refresh'))weatherPanel()}}
$('#weather-card').onclick=weatherPanel;
apply();setInterval(()=>{if(!document.hidden)loadWeather()},1200000);
